#!/bin/bash
# Uninstall script for Nudge
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Nudge..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Nudge if running..."
pkill -f "Nudge" 2>/dev/null || true

# Remove $HOME/Library/Preferences/com.github.macadmins.Nudge.plist
echo "Removing $HOME/Library/Preferences/com.github.macadmins.Nudge.plist..."
if [ -d "$HOME/Library/Preferences/com.github.macadmins.Nudge.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.github.macadmins.Nudge.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.github.macadmins.Nudge.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.github.macadmins.Nudge.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
